-- Oman deep-dive ES/DE/FR translations (completing 259). INSERT OR IGNORE.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Modelo de compensación/reporte Peppol de cinco esquinas por fases (Fawtara), desplegado entre agosto de 2026 y agosto de 2028', 'Esta página de análisis refleja la orientación pública de la OTA y las noticias del sector disponibles a principios de agosto de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. El despliegue de la facturación electrónica de Omán aún se encuentra en sus primeras fases y los criterios de selección de cada ola los determina la OTA — confirme la fase y los requisitos específicos de su empresa directamente con la Autoridad Tributaria de Omán antes de basarse en cualquier fecha aquí indicada.', 'El mandato de facturación electrónica de Omán es genuinamente nuevo — anunciado en octubre de 2025 y desplegado en cuatro fases fechadas hasta agosto de 2028 a través de la plataforma Fawtara de la OTA, en lugar de un sistema con una década de antigüedad como varias otras entradas de este rastreador. La primera ola, que cubre aproximadamente a los 100 mayores contribuyentes, entra en vigor en agosto de 2026; la cobertura B2B nacional completa, incluidas las pymes, sigue en agosto de 2027; las transacciones con contrapartes gubernamentales completan el despliegue en agosto de 2028.', 'Fawtara utiliza PINT-OM (Peppol International Invoice — Oman), una especialización nacional del estándar Peppol BIS Billing, construida sobre XML UBL 2.1. Las facturas B2C requieren además un código QR. No hay ningún esquema propietario omaní independiente que aprender más allá de esta especificación basada en Peppol.', 'Omán ha adoptado un modelo Peppol de cinco esquinas: las facturas se enrutan a través de un Proveedor de Servicios Acreditado (ASP) de la OTA tanto en el lado del proveedor como en el del comprador, con la propia OTA actuando como la quinta esquina, recibiendo un informe y acuse de recibo en tiempo real junto con la entrega al comprador — más cercano al modelo ASP descentralizado de los EAU que al portal de compensación centralizado ZATCA de Arabia Saudita.', 'Cumplir aquí significa averiguar qué fase le corresponde y luego organizar el acceso a un Proveedor de Servicios Acreditado con suficiente antelación — el despliegue de Omán da a las empresas afectadas un aviso previo real mediante contacto directo de la OTA y encuestas de preparación, en lugar de una única fecha fija aplicable a todos a la vez.', 'La OTA aún no ha publicado un calendario de sanciones específico para el incumplimiento de la facturación electrónica en el momento de redactar esto — el marco general de sanciones de la Ley del IVA de Omán presumiblemente se aplicaría entretanto, pero no se han confirmado públicamente cifras específicas de facturación electrónica.', 'Omán está desplegando la facturación electrónica obligatoria en cuatro fases fechadas a través de la plataforma Fawtara de la OTA, un modelo Peppol de cinco esquinas con reporte a la autoridad tributaria en tiempo real. La primera ola — aproximadamente los 100 mayores contribuyentes — entra en vigor en agosto de 2026, ampliándose a todas las empresas registradas a efectos del IVA en agosto de 2027 y a las transacciones con contrapartes gubernamentales en agosto de 2028. Este es uno de los mandatos de facturación electrónica con fechas más concretas e inminentes de la región de Oriente Medio hoy en día.', '🇴🇲' FROM countries WHERE name_en = 'Oman';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Gestaffeltes Peppol-Fünf-Ecken-Clearing-/Meldemodell (Fawtara), Rollout August 2026 – August 2028', 'Diese Länderanalyse spiegelt öffentlich verfügbare OTA-Hinweise und Branchenberichterstattung mit Stand Anfang August 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Omans E-Rechnungs-Rollout befindet sich noch in einer frühen Phase, und die Auswahlkriterien für jede Welle werden von der OTA festgelegt — bestätigen Sie die spezifische Phase und die Anforderungen Ihres Unternehmens direkt bei der omanischen Steuerbehörde, bevor Sie sich auf ein hier genanntes Datum verlassen.', 'Omans E-Rechnungspflicht ist tatsächlich neu — im Oktober 2025 angekündigt und in vier terminierten Phasen bis August 2028 über die Fawtara-Plattform der OTA eingeführt, statt eines jahrzehntealten Systems wie bei mehreren anderen Einträgen dieses Trackers. Die erste Welle, die rund die 100 größten Steuerpflichtigen umfasst, tritt im August 2026 in Kraft; die vollständige inländische B2B-Abdeckung, einschließlich KMU, folgt bis August 2027; Transaktionen mit staatlichen Gegenparteien schließen den Rollout bis August 2028 ab.', 'Fawtara verwendet PINT-OM (Peppol International Invoice — Oman), eine nationale Spezialisierung des Peppol-BIS-Billing-Standards, aufgebaut auf XML UBL 2.1. B2C-Rechnungen benötigen zusätzlich einen QR-Code. Es gibt kein separates proprietäres omanisches Schema zu lernen, das über diese Peppol-basierte Spezifikation hinausgeht.', 'Oman hat ein Peppol-Fünf-Ecken-Modell übernommen: Rechnungen werden sowohl auf Lieferanten- als auch auf Käuferseite über einen von der OTA akkreditierten Dienstanbieter (ASP) geleitet, wobei die OTA selbst als fünfte Ecke fungiert und parallel zur Zustellung an den Käufer einen Echtzeitbericht und eine Bestätigung erhält — näher am dezentralen ASP-Modell der VAE als am zentralisierten ZATCA-Clearing-Portal Saudi-Arabiens.', 'Compliance bedeutet hier, herauszufinden, welche Phase für Sie gilt, und dann rechtzeitig vor diesem Datum den Zugang zu einem akkreditierten Dienstanbieter zu organisieren — Omans Rollout gibt betroffenen Unternehmen durch direkte OTA-Ansprache und Bereitschaftsumfragen echten Vorlauf, statt eines einzigen festen, für alle gleichzeitig geltenden Termins.', 'Die OTA hat zum Zeitpunkt der Abfassung noch keinen spezifischen Bußgeldkatalog für die Nichteinhaltung der E-Rechnungspflicht veröffentlicht — Omans bestehender allgemeiner Sanktionsrahmen des Mehrwertsteuergesetzes würde in der Zwischenzeit vermutlich gelten, aber es wurden keine E-Rechnungs-spezifischen Zahlen öffentlich bestätigt.', 'Oman führt die verpflichtende E-Rechnung in vier terminierten Phasen über die Fawtara-Plattform der OTA ein, ein Peppol-Fünf-Ecken-Modell mit Echtzeit-Meldung an die Steuerbehörde. Die erste Welle — rund die 100 größten Steuerpflichtigen — tritt im August 2026 in Kraft und weitet sich bis August 2027 auf alle mehrwertsteuerregistrierten Unternehmen und bis August 2028 auf Transaktionen mit staatlichen Gegenparteien aus. Dies ist eine der konkretesten, terminierten und unmittelbar bevorstehenden E-Rechnungspflichten in der Nahost-Region heute.', '🇴🇲' FROM countries WHERE name_en = 'Oman';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Modèle de validation/déclaration Peppol à cinq coins par phases (Fawtara), déploiement d''août 2026 à août 2028', 'Cette analyse par pays reflète les orientations publiques de l''OTA et l''actualité du secteur disponibles début août 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Le déploiement de la facturation électronique à Oman en est encore à ses premières phases et les critères de sélection de chaque vague sont déterminés par l''OTA — confirmez la phase et les exigences spécifiques de votre entreprise directement auprès de l''Autorité fiscale d''Oman avant de vous fier à une date indiquée ici.', 'L''obligation de facturation électronique d''Oman est véritablement nouvelle — annoncée en octobre 2025 et déployée en quatre phases datées jusqu''en août 2028 via la plateforme Fawtara de l''OTA, plutôt qu''un système vieux de dix ans comme plusieurs autres entrées de ce suivi. La première vague, couvrant environ les 100 plus grands contribuables, entre en vigueur en août 2026 ; la couverture B2B nationale complète, y compris les PME, suit en août 2027 ; les transactions avec des contreparties gouvernementales achèvent le déploiement en août 2028.', 'Fawtara utilise PINT-OM (Peppol International Invoice — Oman), une spécialisation nationale de la norme Peppol BIS Billing, fondée sur XML UBL 2.1. Les factures B2C nécessitent en outre un code QR. Il n''existe aucun schéma propriétaire omanais distinct à apprendre au-delà de cette spécification fondée sur Peppol.', 'Oman a adopté un modèle Peppol à cinq coins : les factures transitent par un prestataire de services agréé (ASP) de l''OTA du côté du fournisseur comme de l''acheteur, l''OTA elle-même agissant comme cinquième coin, recevant un rapport et un accusé de réception en temps réel parallèlement à la livraison côté acheteur — plus proche du modèle ASP décentralisé des ÉAU que du portail de validation centralisé ZATCA de l''Arabie saoudite.', 'Se conformer ici consiste à déterminer quelle phase s''applique à vous, puis à organiser l''accès à un prestataire de services agréé bien avant cette date — le déploiement d''Oman donne aux entreprises concernées un véritable préavis via une prise de contact directe de l''OTA et des enquêtes de préparation, plutôt qu''une date unique fixe s''appliquant à tous en même temps.', 'L''OTA n''a pas encore publié de barème de sanctions spécifique à la facturation électronique au moment de la rédaction — le cadre général de sanctions de la loi omanaise sur la TVA s''appliquerait vraisemblablement dans l''intervalle, mais aucun chiffre spécifique à la facturation électronique n''a été confirmé publiquement.', 'Oman déploie la facturation électronique obligatoire en quatre phases datées via la plateforme Fawtara de l''OTA, un modèle Peppol à cinq coins avec déclaration en temps réel à l''autorité fiscale. La première vague — environ les 100 plus grands contribuables — entre en vigueur en août 2026, s''étendant à toutes les entreprises immatriculées à la TVA d''ici août 2027 et aux transactions avec des contreparties gouvernementales d''ici août 2028. C''est l''une des obligations de facturation électronique les plus concrètement datées et imminentes de la région Moyen-Orient aujourd''hui.', '🇴🇲' FROM countries WHERE name_en = 'Oman';

