INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato y estándar', '[["Estándar", "PINT-OM (Peppol International Invoice — Oman), una especialización nacional de Peppol BIS Billing"], ["Formato base", "XML, UBL 2.1"], ["Requisito B2C", "Código QR obligatorio en toda factura dirigida al consumidor"], ["Base legal", "Reglamentos de la Autoridad Tributaria de Omán bajo la Ley del IVA, implementados a través del programa Fawtara"]]', 'No hay ningún esquema propietario omaní independiente que aprender — PINT-OM es una especificación basada en Peppol, la misma familia de estándar utilizada por los EAU y varios países de Asia-Pacífico en este rastreador.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Format & Standard', '[["Standard", "PINT-OM (Peppol International Invoice — Oman), eine nationale Spezialisierung von Peppol BIS Billing"], ["Basisformat", "XML, UBL 2.1"], ["B2C-Anforderung", "Verpflichtender QR-Code auf jeder verbraucherbezogenen Rechnung"], ["Rechtsgrundlage", "Vorschriften der omanischen Steuerbehörde nach dem Mehrwertsteuergesetz, umgesetzt über das Fawtara-Programm"]]', 'Es gibt kein separates proprietäres omanisches Schema zu lernen — PINT-OM ist eine Peppol-basierte Spezifikation, dieselbe Standardfamilie, die von den VAE und mehreren asiatisch-pazifischen Ländern in diesem Tracker verwendet wird.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format et norme', '[["Norme", "PINT-OM (Peppol International Invoice — Oman), une spécialisation nationale de Peppol BIS Billing"], ["Format de base", "XML, UBL 2.1"], ["Exigence B2C", "Code QR obligatoire sur chaque facture destinée au consommateur"], ["Base légale", "Réglementations de l''Autorité fiscale d''Oman en vertu de la loi sur la TVA, mises en œuvre via le programme Fawtara"]]', 'Il n''existe aucun schéma propriétaire omanais distinct à apprendre — PINT-OM est une spécification fondée sur Peppol, la même famille de norme utilisée par les ÉAU et plusieurs pays d''Asie-Pacifique dans ce suivi.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'file_format' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Identificadores y registro', '[["Vía de acceso", "Un Proveedor de Servicios Acreditado (ASP) de la OTA — sin carga directa en un portal gubernamental"], ["Registro de ASP abierto", "Mayo de 2026"], ["Portal de desarrollador/pruebas abierto", "Febrero de 2026"], ["Organismo regulador", "Autoridad Tributaria de Omán (OTA)"]]', 'Al igual que los EAU, Omán enruta cada factura a través de un intermediario certificado en lugar de un portal de compensación gubernamental directo — designar un ASP es el primer paso práctico para cualquier empresa afectada.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Kennungen & Registrierung', '[["Zugangsweg", "Ein von der OTA akkreditierter Dienstanbieter (ASP) — kein direkter Upload über ein Regierungsportal"], ["ASP-Registrierung eröffnet", "Mai 2026"], ["Entwickler-/Testportal eröffnet", "Februar 2026"], ["Aufsichtsbehörde", "Omanische Steuerbehörde (OTA)"]]', 'Wie die VAE leitet Oman jede Rechnung über einen zertifizierten Vermittler statt über ein direktes staatliches Clearing-Portal — die Beauftragung eines ASP ist der praktische erste Schritt für jedes betroffene Unternehmen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Identifiants et enregistrement', '[["Voie d''accès", "Un prestataire de services agréé (ASP) de l''OTA — aucun téléversement direct sur un portail gouvernemental"], ["Enregistrement des ASP ouvert", "Mai 2026"], ["Portail de développement/test ouvert", "Février 2026"], ["Organisme de contrôle", "Autorité fiscale d''Oman (OTA)"]]', 'Comme les ÉAU, Oman achemine chaque facture via un intermédiaire certifié plutôt que par un portail de validation gouvernemental direct — désigner un ASP est la première étape pratique pour toute entreprise concernée.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'file_format' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Contenido obligatorio', '[["Modelo base", "Campos base de Peppol BIS Billing 3.0, ampliados por el diccionario de datos PINT-OM"], ["Ventana de reporte", "Envío casi en tiempo real a la OTA junto con la entrega al comprador"], ["Facturas B2C", "Deben llevar además un código QR"]]', 'El requisito de reporte casi en tiempo real acerca a Omán, estructuralmente, más a un modelo de compensación que a uno de post-auditoría puro, aunque la propia OTA nunca bloquea ni aprueba una factura como sí lo hace el portal ZATCA de Arabia Saudita.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtinhalte', '[["Kernmodell", "Basisfelder von Peppol BIS Billing 3.0, erweitert um das PINT-OM-Datenverzeichnis"], ["Meldefenster", "Nahezu Echtzeit-Übermittlung an die OTA parallel zur Zustellung an den Käufer"], ["B2C-Rechnungen", "Müssen zusätzlich einen QR-Code tragen"]]', 'Die Anforderung der nahezu Echtzeit-Meldung rückt Oman strukturell näher an ein Clearing-Modell als an ein reines Post-Audit-Modell, auch wenn die OTA selbst nie eine Rechnung blockiert oder genehmigt, wie es das ZATCA-Portal Saudi-Arabiens tut.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Contenu obligatoire', '[["Modèle de base", "Champs de base de Peppol BIS Billing 3.0, étendus par le dictionnaire de données PINT-OM"], ["Fenêtre de déclaration", "Soumission quasi en temps réel à l''OTA parallèlement à la livraison à l''acheteur"], ["Factures B2C", "Doivent en outre comporter un code QR"]]', 'L''exigence de déclaration quasi en temps réel rapproche structurellement Oman d''un modèle de validation préalable plutôt que d''un modèle purement post-audit, même si l''OTA elle-même ne bloque ni n''approuve jamais une facture comme le fait le portail ZATCA de l''Arabie saoudite.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'file_format' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'Las cinco esquinas', 'Toda factura bajo Fawtara pasa por la misma secuencia de cinco esquinas:', 'El acuse de recibo de la OTA (esquina 5) llega en paralelo a la entrega al comprador, no como un paso posterior separado — esto es lo que hace que el modelo sea casi en tiempo real en lugar de un simple intercambio de 4 esquinas con reporte posterior añadido.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Oman' AND lc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Die fünf Ecken', 'Jede Rechnung unter Fawtara durchläuft dieselbe Fünf-Ecken-Sequenz:', 'Die Bestätigung der OTA (Ecke 5) erfolgt parallel zur Zustellung an den Käufer, nicht als separater späterer Schritt — das macht das Modell nahezu echtzeitfähig statt eines einfachen 4-Ecken-Austauschs mit nachträglich angehängter Meldung.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Oman' AND lc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Les cinq coins', 'Chaque facture sous Fawtara suit la même séquence à cinq coins :', 'L''accusé de réception de l''OTA (coin 5) arrive en parallèle de la livraison à l''acheteur, non comme une étape ultérieure distincte — c''est ce qui rend le modèle quasi temps réel plutôt qu''un simple échange à 4 coins avec un rapport ajouté après coup.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Oman' AND lc.sort_order = 0;

