INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'L''acheteur reçoit + l''OTA est informée' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON lc.id = ls.card_id JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'Oman' AND ls.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Lo que realmente exige cada fase', '[["Fase 1 (ago. 2026)", "Aproximadamente los 100 mayores contribuyentes, seleccionados por tamaño, volumen de transacciones, sector, geografía y perfil de riesgo"], ["Fase 2 (feb. 2027)", "Grandes contribuyentes restantes no cubiertos por la Fase 1"], ["Fase 3 (ago. 2027)", "Todo contribuyente restante registrado a efectos del IVA, incluidas las pymes"], ["Fase 4 (ago. 2028)", "Organismos gubernamentales, como contrapartes de facturación electrónica"]]', 'A diferencia de una única fecha fija de entrada en vigor, el despliegue de Omán da a cada ola entre seis y doce meses de aviso — la pregunta práctica para la mayoría de las empresas es qué fase les corresponde, no si alguna eventualmente lo hará.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Was jede Phase tatsächlich verlangt', '[["Phase 1 (Aug. 2026)", "Rund die 100 größten Steuerpflichtigen, ausgewählt nach Größe, Transaktionsvolumen, Branche, Geografie und Risikoprofil"], ["Phase 2 (Feb. 2027)", "Verbleibende Großsteuerpflichtige, die nicht von Phase 1 erfasst wurden"], ["Phase 3 (Aug. 2027)", "Jeder verbleibende mehrwertsteuerregistrierte Steuerpflichtige, einschließlich KMU"], ["Phase 4 (Aug. 2028)", "Regierungsstellen, als E-Rechnungs-Gegenparteien"]]', 'Anders als ein einziger fester Starttermin gibt Omans Rollout jeder Welle etwa sechs bis zwölf Monate Vorlauf — die praktische Frage für die meisten Unternehmen ist, welche Phase für sie gilt, nicht ob irgendwann eine gelten wird.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Ce que chaque phase exige réellement', '[["Phase 1 (août 2026)", "Environ les 100 plus grands contribuables, sélectionnés selon la taille, le volume de transactions, le secteur, la géographie et le profil de risque"], ["Phase 2 (févr. 2027)", "Grands contribuables restants non couverts par la Phase 1"], ["Phase 3 (août 2027)", "Tout contribuable restant immatriculé à la TVA, y compris les PME"], ["Phase 4 (août 2028)", "Organismes gouvernementaux, en tant que contreparties de facturation électronique"]]', 'Contrairement à une date d''entrée en vigueur unique et fixe, le déploiement d''Oman donne à chaque vague environ six à douze mois de préavis — la question pratique pour la plupart des entreprises est de savoir quelle phase s''applique à elles, non si l''une d''elles s''appliquera un jour.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Participación voluntaria antes de su fase', '[["Quién puede unirse antes", "Cualquier empresa registrada a efectos del IVA que aún no esté en una fase obligatoria"], ["Por qué puede tener sentido", "Completar la integración con el ASP y los cambios de ERP antes de una fecha límite estricta, en lugar de contrarreloj"], ["Coste de esperar", "Nada específico publicado todavía, más allá del riesgo general de una implementación comprimida"]]', 'Omán permite explícitamente la participación voluntaria anticipada para las empresas fuera de la ola actual — una forma de menor presión para tener lista la infraestructura de cumplimiento antes de que sea legalmente obligatoria.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Freiwillige Teilnahme vor Ihrer Phase', '[["Wer früher teilnehmen kann", "Jedes mehrwertsteuerregistrierte Unternehmen, das noch nicht in einer Pflichtphase ist"], ["Warum das sinnvoll sein könnte", "ASP-Integration und ERP-Änderungen vor einer harten Frist erledigen, statt dagegen anzukämpfen"], ["Kosten des Wartens", "Noch nichts Spezifisches veröffentlicht, abgesehen vom allgemeinen Risiko eines komprimierten Umsetzungszeitplans"]]', 'Oman erlaubt ausdrücklich eine freiwillige frühzeitige Teilnahme für Unternehmen außerhalb der aktuellen Welle — eine Möglichkeit mit geringerem Druck, konforme Infrastruktur einzurichten, bevor sie gesetzlich vorgeschrieben ist.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Participation volontaire avant votre phase', '[["Qui peut rejoindre plus tôt", "Toute entreprise immatriculée à la TVA pas encore dans une phase obligatoire"], ["Pourquoi cela peut avoir du sens", "Réaliser l''intégration ASP et les changements ERP avant une échéance stricte, plutôt que dans l''urgence"], ["Coût de l''attente", "Rien de spécifique publié pour l''instant, au-delà du risque général d''une mise en œuvre comprimée"]]', 'Oman autorise explicitement une participation volontaire anticipée pour les entreprises en dehors de la vague actuelle — un moyen moins contraignant de mettre en place une infrastructure conforme avant qu''elle ne soit légalement exigée.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '📋 Aún sin calendario de sanciones específico para la facturación electrónica', NULL, NULL, 'En el momento de redactar esto, la OTA no ha publicado una estructura de multas específica para el incumplimiento de la facturación electrónica. El marco general de sanciones de la Ley del IVA de Omán presumiblemente se aplicaría entretanto, pero no se han confirmado públicamente cifras específicas de facturación electrónica — con límite o sin él.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📋 Noch kein veröffentlichter E-Rechnungs-spezifischer Bußgeldkatalog', NULL, NULL, 'Zum Zeitpunkt der Abfassung hat die OTA keine spezifische Bußgeldstruktur für die Nichteinhaltung der E-Rechnungspflicht veröffentlicht. Omans bestehender allgemeiner Sanktionsrahmen des Mehrwertsteuergesetzes würde in der Zwischenzeit vermutlich gelten, aber es wurden keine E-Rechnungs-spezifischen Zahlen — gedeckelt oder anderweitig — öffentlich bestätigt.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📋 Aucun barème de sanctions spécifique à la facturation électronique publié pour l''instant', NULL, NULL, 'Au moment de la rédaction, l''OTA n''a publié aucune structure d''amendes spécifique à la non-conformité en matière de facturation électronique. Le cadre général de sanctions de la loi omanaise sur la TVA s''appliquerait vraisemblablement dans l''intervalle, mais aucun chiffre spécifique à la facturation électronique — plafonné ou non — n''a été confirmé publiquement.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'penalties_related' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🗓️ Un despliegue por fases construido en torno al contacto directo', NULL, NULL, 'En lugar de una única fecha límite sorpresa, la OTA ha notificado directamente a los contribuyentes de la Fase 1 y la Fase 2 y ha realizado encuestas de preparación técnica (octubre de 2025 para la Fase 1, abril de 2026 para la Fase 2) antes de cada entrada en vigor — un estilo de despliegue más consultivo que varios otros mandatos de este rastreador.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🗓️ Ein gestaffelter Rollout, aufgebaut auf direkter Ansprache', NULL, NULL, 'Statt eines einzigen überraschenden Stichtags hat die OTA Phase-1- und Phase-2-Steuerpflichtige direkt benachrichtigt und vor jedem Starttermin technische Bereitschaftsumfragen durchgeführt (Oktober 2025 für Phase 1, April 2026 für Phase 2) — ein konsultativerer Rollout-Stil als bei mehreren anderen Pflichten in diesem Tracker.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🗓️ Un déploiement par phases construit autour d''un contact direct', NULL, NULL, 'Plutôt qu''une échéance surprise unique, l''OTA a directement notifié les contribuables de Phase 1 et de Phase 2 et mené des enquêtes de préparation technique (octobre 2025 pour la Phase 1, avril 2026 pour la Phase 2) avant chaque entrée en vigueur — un style de déploiement plus consultatif que plusieurs autres obligations de ce suivi.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'penalties_related' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '📡 Vigile las comunicaciones oficiales de la OTA, no solo esta tabla', NULL, NULL, 'Dado que la selección de fase depende de criterios específicos de la OTA (tamaño, volumen, sector, geografía, perfil de riesgo) en lugar de un umbral público de ingresos, la forma más fiable de conocer su propia fecha de entrada en vigor es la notificación directa de la OTA o consultar directamente el portal Fawtara, no los comentarios generales.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📡 Beobachten Sie offizielle OTA-Mitteilungen, nicht nur diese Tabelle', NULL, NULL, 'Da die Phasenzuordnung von OTA-spezifischen Kriterien (Größe, Volumen, Branche, Geografie, Risikoprofil) statt von einem öffentlichen Umsatzschwellenwert abhängt, ist die zuverlässigste Methode, Ihr eigenes Starttermin zu erfahren, die direkte Benachrichtigung durch die OTA oder die direkte Prüfung des Fawtara-Portals, nicht allgemeine Branchenkommentare.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📡 Surveillez les communications officielles de l''OTA, pas seulement ce tableau', NULL, NULL, 'La sélection de phase dépendant de critères propres à l''OTA (taille, volume, secteur, géographie, profil de risque) plutôt que d''un seuil de revenus public, le moyen le plus fiable de connaître votre propre date d''entrée en vigueur est la notification directe de l''OTA ou la consultation directe du portail Fawtara, non les commentaires généraux du secteur.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Oman' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Determine qué fase le corresponde', 'Compruebe si la OTA le ha identificado como empresa de la Fase 1 (mayores contribuyentes) o de la Fase 2 (grandes contribuyentes restantes) — de lo contrario, quedará sujeto por defecto al requisito universal de la Fase 3 de 2027.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Oman' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestimmen Sie, welche Phase für Ihr Unternehmen gilt', 'Prüfen Sie, ob die OTA Sie als Phase-1-Unternehmen (größte Steuerpflichtige) oder Phase-2-Unternehmen (verbleibende Großsteuerpflichtige) identifiziert hat — andernfalls fallen Sie standardmäßig unter die universelle Anforderung von Phase 3 im Jahr 2027.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Oman' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Déterminez quelle phase s''applique à votre entreprise', 'Vérifiez si l''OTA vous a identifié comme entreprise de Phase 1 (plus grands contribuables) ou de Phase 2 (grands contribuables restants) — sinon, vous relevez par défaut de l''exigence universelle de la Phase 3 de 2027.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Oman' AND ds.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Designe un Proveedor de Servicios Acreditado (ASP)', 'Toda empresa necesita un ASP certificado para emitir y recibir facturas electrónicas de Fawtara — el registro se abrió en mayo de 2026, por lo que esta es la primera decisión práctica de infraestructura a tomar.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Oman' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Beauftragen Sie einen akkreditierten Dienstanbieter (ASP)', 'Jedes Unternehmen benötigt einen zertifizierten ASP, um Fawtara-E-Rechnungen auszustellen und zu empfangen — die Registrierung wurde im Mai 2026 eröffnet, dies ist also die erste praktische Infrastrukturentscheidung.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Oman' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Désignez un prestataire de services agréé (ASP)', 'Chaque entreprise a besoin d''un ASP certifié pour émettre et recevoir des factures électroniques Fawtara — l''enregistrement a ouvert en mai 2026, il s''agit donc de la première décision pratique d''infrastructure à prendre.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Oman' AND ds.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Prepare los sistemas de ERP o facturación para la salida estructurada', 'Confirme que sus sistemas pueden generar facturas conformes con PINT-OM/UBL 2.1, incluido un código QR para las facturas B2C, antes de la fecha de entrada en vigor de su fase.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Oman' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bereiten Sie ERP- oder Rechnungssysteme auf strukturierte Ausgabe vor', 'Bestätigen Sie, dass Ihre Systeme PINT-OM-/UBL-2.1-konforme Rechnungen erzeugen können, einschließlich eines QR-Codes für B2C-Rechnungen, vor dem Starttermin Ihrer Phase.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Oman' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Préparez vos systèmes ERP ou de facturation à la sortie structurée', 'Confirmez que vos systèmes peuvent produire des factures conformes à PINT-OM/UBL 2.1, y compris un code QR pour les factures B2C, avant la date d''entrée en vigueur de votre phase.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Oman' AND ds.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Considere la participación voluntaria anticipada', 'Si aún no está en una fase obligatoria, completar el trabajo de ASP y ERP antes de una fecha límite estricta evita una implementación comprimida y de última hora.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Oman' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Erwägen Sie eine freiwillige frühzeitige Teilnahme', 'Falls Sie noch nicht in einer Pflichtphase sind, vermeidet die Erledigung von ASP- und ERP-Arbeiten vor einer harten Frist eine komprimierte Umsetzung in letzter Minute.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Oman' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Envisagez une participation volontaire anticipée', 'Si vous n''êtes pas encore dans une phase obligatoire, réaliser le travail ASP et ERP avant une échéance stricte évite une mise en œuvre comprimée de dernière minute.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Oman' AND ds.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Siga directamente las comunicaciones oficiales de la OTA', 'La selección de fase depende de criterios específicos de la OTA, no de un único umbral público — las notificaciones directas y el portal Fawtara son más fiables que los comentarios generales del sector.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Oman' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Verfolgen Sie offizielle OTA-Mitteilungen direkt', 'Die Phasenzuordnung hängt von OTA-spezifischen Kriterien ab, nicht von einem einzigen öffentlichen Schwellenwert — direkte Benachrichtigungen und das Fawtara-Portal sind zuverlässiger als allgemeine Branchenkommentare.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Oman' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Suivez directement les communications officielles de l''OTA', 'La sélection de phase dépend de critères propres à l''OTA, non d''un seuil public unique — les notifications directes et le portail Fawtara sont plus fiables que les commentaires généraux du secteur.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Oman' AND ds.sort_order = 4;

